  // What a person's parts move: added for the parts they hold, taken off for the parts of their own claims.
  const partsOf = (person: Person, which: (c: (typeof live)[number]) => boolean) =>
    parts.reduce(
      (sum, p) => (!which(p.claim) ? sum : sum + (p.holderId === person.id ? p.part : 0n) - (p.ownerId === person.id ? p.part : 0n)),
      0n,
    );
  // A claim is worked at the grade in force on its date; the row shows the one in force today.
  // The sum of a person's figures, before the cap, with their parts; holding a part is a figure.
  const uncappedOf = (person: Person) => {
    const own = dueTotal(
      live.filter((c) => c.personId === person.id),
      (c) => claimRate(rates, gradeOn(person, c.date), c),
      rateOn(rates, gradeOn(person, today), today),
      floor,
      late,
      policy,
    );
    if (own === null && !parts.some((p) => p.holderId === person.id)) return null;
    return (own ?? 0n) + partsOf(person, () => true);
  };
  // A person's cut total: their cuts in every pool added up.
  const cutOf = (personId: string) =>
    pools.reduce(
      (sum, pool) => pool.members.reduce((s, m) => (m.personId === personId && m.cut !== '' ? s + toCents(m.cut) : s), sum),
      0n,
    );
  // A person's due-total: at most the sheet's cap less their cut total, not below 0.00 (n/a is not capped);
  // everything that adds up due-totals uses it. Their excess is how far the sum of their figures is above that.
  const totalOf = (person: Person) => capped(uncappedOf(person), cap, cutOf(person.id));
  const excessOf = (person: Person) => excess(uncappedOf(person), cap, cutOf(person.id));
  // A person's settled-total and open-total: the dues of their counting SETTLED claims (frozen
  // figures, corrections included), and of their counting OPEN and PENDING claims; n/a adds nothing.
  // Together they make the sum of their figures before the cap.
  const dueSumOf = (person: Person, which: (c: (typeof live)[number]) => boolean) =>
    live
      .filter((c) => c.personId === person.id && which(c))
      .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(person, c.date), c), floor, late, policy) ?? 0n), 0n);
  // Each counts the person's parts of those claims the same way.
  const settledOf = (c: (typeof live)[number]) => c.status === 'SETTLED';
  const settledTotalOf = (person: Person) => dueSumOf(person, settledOf) + partsOf(person, settledOf);
  const openTotalOf = (person: Person) => dueSumOf(person, isOpen) + partsOf(person, isOpen);
  // The sheet's settled-total and open-total: everyone's figure added up, not trimmed.
  const sheetSettledTotal = formatCents(people.reduce((sum, p) => sum + settledTotalOf(p), 0n));
  const sheetOpenTotal = formatCents(people.reduce((sum, p) => sum + openTotalOf(p), 0n));
  const overdue = live.filter((c) => isOverdue(c, today, grace));
  const overdueSum = (cs: typeof overdue) =>
    cs.reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(byId.get(c.personId)!, c.date), c), floor, late, policy) ?? 0n), 0n);
  const overdueTotal = (cs: typeof overdue) => formatCents(overdueSum(cs));
  // A person's score: the dues of their counting SETTLED claims that correct nothing, over 100,
  // minus 5 for each of their overdue counting claims, rounded half to even to a whole number.
  const scoreOf = (person: Person) => {
    const overdueCount = BigInt(overdue.filter((c) => c.personId === person.id).length);
    const settled = dueSumOf(person, (c) => c.status === 'SETTLED' && !c.corrects);
    return halfEvenDiv(settled - overdueCount * 50000n, 10000n).toString();
  };
  // Each person's due-total, skipping n/a, and overdue-total (always a figure), in list order.
