  });
  // What a person's parts move: added for the parts they hold, taken off for the parts of their own claims.
  const partsOf = (person: Person, which: (c: (typeof live)[number]) => boolean) =>
    parts.reduce(
      (sum, p) => (!which(p.claim) ? sum : sum + (p.holderId === person.id ? p.part : 0n) - (p.ownerId === person.id ? p.part : 0n)),
      0n,
    );
  // A claim is worked at the grade in force on its date; the row shows the one in force today.
  // The sum of a person's figures, before the cap, with their parts; holding a part is a figure.
  const uncappedOf = (person: Person) => {
    const own = dueTotal(
      live.filter((c) => c.personId === person.id),
      (c) => claimRate(rates, gradeOn(person, c.date), c),
      rateOn(rates, gradeOn(person, today), today),
      floor,
      late,
      policy,
    );
    if (own === null && !parts.some((p) => p.holderId === person.id)) return null;
    return (own ?? 0n) + partsOf(person, () => true);
  };
  // A person's cut total: their cuts in every pool added up.
  const cutOf = (personId: string) =>
    pools.reduce(
      (sum, pool) => pool.members.reduce((s, m) => (m.personId === personId && m.cut !== '' ? s + toCents(m.cut) : s), sum),
      0n,
    );
  // A person's due-total: at most the sheet's cap less their cut total, not below 0.00 (n/a is not capped);
  // everything that adds up due-totals uses it. Their excess is how far the sum of their figures is above that.
  const totalOf = (person: Person) => capped(uncappedOf(person), cap, cutOf(person.id));
  const excessOf = (person: Person) => excess(uncappedOf(person), cap, cutOf(person.id));
  // A person's settled-total and open-total: the dues of their counting SETTLED claims (frozen
  // figures, corrections included), and of their counting OPEN and PENDING claims; n/a adds nothing.
  // Together they make the sum of their figures before the cap.
  const dueSumOf = (person: Person, which: (c: (typeof live)[number]) => boolean) =>
    live
      .filter((c) => c.personId === person.id && which(c))
      .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(person, c.date), c), floor, late, policy) ?? 0n), 0n);
  // Each counts the person's parts of those claims the same way.
  const settledOf = (c: (typeof live)[number]) => c.status === 'SETTLED';
  const settledTotalOf = (person: Person) => dueSumOf(person, settledOf) + partsOf(person, settledOf);
  const openTotalOf = (person: Person) => dueSumOf(person, isOpen) + partsOf(person, isOpen);
  // The sheet's settled-total and open-total: everyone's figure added up, not trimmed.
  const sheetSettledTotal = formatCents(people.reduce((sum, p) => sum + settledTotalOf(p), 0n));
  const sheetOpenTotal = formatCents(people.reduce((sum, p) => sum + openTotalOf(p), 0n));
  const overdue = live.filter((c) => isOverdue(c, today, grace));
  const overdueSum = (cs: typeof overdue) =>
    cs.reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(byId.get(c.personId)!, c.date), c), floor, late, policy) ?? 0n), 0n);
  const overdueTotal = (cs: typeof overdue) => formatCents(overdueSum(cs));
  // A person's score: the dues of their counting SETTLED claims that correct nothing, over 100,
  // minus 5 for each of their overdue counting claims, rounded half to even to a whole number.
  const scoreOf = (person: Person) => {
    const overdueCount = BigInt(overdue.filter((c) => c.personId === person.id).length);
    const settled = dueSumOf(person, (c) => c.status === 'SETTLED' && !c.corrects);
    return halfEvenDiv(settled - overdueCount * 50000n, 10000n).toString();
  };
  // Each person's due-total, skipping n/a, and overdue-total (always a figure), in list order.
  const dueFigures = people.map(totalOf).filter((due): due is bigint => due !== null);
  const overdueFigures = people.map((p) => overdueSum(overdue.filter((c) => c.personId === p.id)));
  // The sheet's due-total and overdue-total: those figures added up, trimmed.
  const sheetDueTotal = formatCents(trimmedSum(dueFigures));
  const sheetOverdueTotal = formatCents(trimmedSum(overdueFigures));
  // Active: an OPEN or PENDING claim that counts, dated within the 30 days up to and including today.
  const activeFrom = today === undefined ? undefined : daysBefore(today, 29);
  const isActive = (person: Person) =>
    activeFrom !== undefined &&
    live.some((c) => c.personId === person.id && isOpen(c) && c.date >= activeFrom && c.date <= today!);
  // Settled: the sum of a person's SETTLED claims' frozen figures, dated within the 90 days up to and including today.
  const settledFrom = today === undefined ? undefined : daysBefore(today, 89);
  const recentSettledOf = (person: Person) =>
    settledFrom === undefined
      ? 0n
      : claims
          .filter((c) => c.personId === person.id && c.status === 'SETTLED' && c.date >= settledFrom && c.date <= today! && /^-?\d+\.\d{2}$/.test(c.due))
          .reduce((sum, c) => sum + toCents(c.due), 0n);
  // Aged: the dues of a person's OPEN and PENDING claims that count, split by the claim's age on
  // today (days from its date): 0 to 30, 31 to 60, 61 or more; a claim dated after today is 0 to 30.
  const agedOf = (person: Person) => {
    const buckets = [0n, 0n, 0n];
    if (today === undefined) return buckets;
    for (const c of live) {
      if (c.personId !== person.id || !isOpen(c)) continue;
      const age = daysBetween(c.date, today);
      const due = claimDue(c, claimRate(rates, gradeOn(person, c.date), c), floor, late, policy) ?? 0n;
      buckets[age <= 30 ? 0 : age <= 60 ? 1 : 2] += due;
    }
    return buckets;
  };
  // The sheet's aged buckets: the people's buckets added up, not trimmed.
  const sheetAged = people
    .map(agedOf)
    .reduce((sum, b) => sum.map((v, i) => v + b[i]), [0n, 0n, 0n])
    .map(formatCents);
  // Each tag ever used on the sheet with its due-total: the dues of the counting claims that carry it,
  // or whose person carries it, each claim once (a claim with two tags counts in both); n/a adds nothing.
  const tagTotals = tags.map((tag) => ({
    tag,
    total: formatCents(
      live
        .filter((c) => hasTag(c, tag) || hasTag(byId.get(c.personId)!, tag))
        .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(byId.get(c.personId)!, c.date), c), floor, late, policy) ?? 0n), 0n),
    ),
  }));
  const onSheet = new Set(people.map((p) => p.id));
  const sheetClaims = claims.filter((c) => onSheet.has(c.personId));
  // Each calendar month (yyyy-mm) any claim on the sheet is dated in, earliest first, with its
  // due-total: the dues of the counting claims dated in it; n/a adds nothing.
  const monthTotals = [...new Set(sheetClaims.map((c) => c.date.slice(0, 7)))].sort().map((month) => ({
    month,
    total: formatCents(
      live
        .filter((c) => c.date.slice(0, 7) === month)
        .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(byId.get(c.personId)!, c.date), c), floor, late, policy) ?? 0n), 0n),
    ),
  }));
  const statusCount = (s: (typeof STATUSES)[number]) => sheetClaims.filter((c) => c.status === s).length;
  // Review-late: REVIEW claims whose review day plus the sheet's review SLA is before the sheet's today.
  const reviewLateCount = sheetClaims.filter((c) => isReviewLate(c, today, reviewSla)).length;
  // Pending-late: PENDING claims whose pending day plus the sheet's pending SLA is before the sheet's today.
  const pendingLateCount = sheetClaims.filter((c) => isPendingLate(c, today, pendingSla)).length;
  const voidReasonCount = (reason: string) => sheetClaims.filter((c) => c.status === 'VOID' && c.voidReason === reason).length;
  return { people, claims, rates, today, byId, live, claimedLive, cutOf, totalOf, excessOf, overdue, overdueTotal, dueFigures, overdueFigures, sheetDueTotal, sheetOverdueTotal, statusCount, reviewLateCount, pendingLateCount, voidReasonCount, isActive, recentSettledOf, agedOf, sheetAged, settledTotalOf, openTotalOf, scoreOf, sheetSettledTotal, sheetOpenTotal, tagTotals, monthTotals };
}

// People's figures added up, leaving out the single highest and the single lowest when there are
// three or more.
export function trimmedSum(figures: bigint[]): bigint {
  const sum = figures.reduce((a, b) => a + b, 0n);
  if (figures.length < 3) return sum;
  const max = figures.reduce((a, b) => (b > a ? b : a));
  const min = figures.reduce((a, b) => (b < a ? b : a));
  return sum - max - min;
}

// The ISO date `days` days before `date`.
function daysBefore(date: string, days: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() - days);
  return d.toISOString().slice(0, 10);
}
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useGradeCodes } from '../grades/useGrades';
import { gradeOn } from '../people/usePeople';
import { STATUSES, trimmedSum, useSheetFigures } from '../people/useSheetFigures';
import { formatCents } from '../rates/due';
import { useDescendants } from './useDescendants';

type Totals = { people: string[][]; due: bigint[]; overdue: bigint[]; grades: bigint[]; statuses: number[] };

// The root sheet's grades, the order of Totals.grades.
type Grades = string[];

// The figures over the sheet and all its descendants: their people, each counted once across the
// tree (people whose names or aliases match, as names are compared, are one person); the due-total
// and overdue-total, every person's figure over the tree (n/a skipped for due) added up, leaving out
// the single highest and the single lowest when there are three or more. Per grade, the due-totals of the people on it
// today (retired people left out, n/a skipped) as each sheet's summary shows them, added up; per
// status, how many claims have it, added up. A sheet with no children shows its own. While the
// screen is shown as of a date, so are they: every sheet of the tree as it stood at the end of that day,
// with that date as its today.
export function ConsolidatedFigures() {
  const [sheet] = useSearchParam('sheet', asString);
  const descendants = useDescendants(sheet);
  const grades = useGradeCodes(sheet);
  return (
    <Add sheets={[sheet, ...descendants]} grades={grades} totals={{ people: [], due: [], overdue: [], grades: grades.map(() => 0n), statuses: STATUSES.map(() => 0) }} />
  );
}

// Adds the first sheet's figures to the totals and passes on to the rest: one sheet's hooks per
// component, so the number of sheets can change.
function Add({ sheets, grades, totals }: { sheets: string[]; grades: Grades; totals: Totals }) {
  if (sheets.length === 0) return <Shown grades={grades} totals={totals} />;
  return <AddSheet key={sheets[0]} sheets={sheets} grades={grades} totals={totals} />;
}

function AddSheet({ sheets, grades, totals }: { sheets: string[]; grades: Grades; totals: Totals }) {
  const { people, today, totalOf, statusCount, dueFigures, overdueFigures } = useSheetFigures(sheets[0]);
  const current = people.filter((p) => !p.retired);
  const gradeDue = (g: string) =>
    current.filter((p) => gradeOn(p, today) === g).reduce((sum, p) => sum + (totalOf(p) ?? 0n), 0n);
  return (
    <Add
      sheets={sheets.slice(1)}
      grades={grades}
      totals={{
        people: [...totals.people, ...people.map((p) => [p.name, ...p.aliases].map(nameKey))],
        due: [...totals.due, ...dueFigures],
        overdue: [...totals.overdue, ...overdueFigures],
        grades: grades.map((g, i) => (totals.grades[i] ?? 0n) + gradeDue(g)),
        statuses: STATUSES.map((s, i) => totals.statuses[i] + statusCount(s)),
      }}
    />
  );
}

// A name as names are compared: without regard to case or outer spaces.
const nameKey = (name: string) => name.trim().toLowerCase();

// How many people there are when those sharing a name or alias (directly or through others) are one.
function distinctPeople(people: string[][]): number {
  const parent = people.map((_, i) => i);
  const find = (i: number): number => (parent[i] === i ? i : (parent[i] = find(parent[i])));
  const holder = new Map<string, number>();
  people.forEach((keys, i) =>
    keys.forEach((k) => {
      const j = holder.get(k);
      if (j === undefined) holder.set(k, i);
      else parent[find(i)] = find(j);
    }),
  );
  return people.filter((_, i) => find(i) === i).length;
}

function Shown({ grades, totals }: { grades: Grades; totals: Totals }) {
  return (
    <section data-testid="consolidated">
      Consolidated — People: <span data-testid="consolidated-people-count">{distinctPeople(totals.people)}</span>
      {' · '}Due: <span data-testid="consolidated-due-total">{formatCents(trimmedSum(totals.due))}</span>
      {' · '}Overdue: <span data-testid="consolidated-overdue-total">{formatCents(trimmedSum(totals.overdue))}</span>
      {grades.map((g, i) => (
        <span key={g}>
          {' · '}Grade {g}: <span data-testid={`consolidated-grade-${g}-due-total`}>{formatCents(totals.grades[i])}</span>
        </span>
      ))}
      {STATUSES.map((s, i) => (
        <span key={s}>
          {' · '}{s}: <span data-testid={`consolidated-status-${s}-count`}>{totals.statuses[i]}</span>
        </span>
      ))}
    </section>
  );
}

